package store

import "fmt"

// SeatError says a change needs a seat the organization's plan does not have. Limit is the plan's limit and Used the
// seats in use.
type SeatError struct {
	Limit int
	Used  int
}

func (e *SeatError) Error() string {
	return fmt.Sprintf("the plan allows %d seats and %d are in use", e.Limit, e.Used)
}

// Seats is an organization's seat use. Limit is nil when its plan has no limit.
type Seats struct {
	Used  int  `json:"used"`
	Limit *int `json:"limit"`
}

// Seats returns an organization's seat use: its members and pending invites whose role is not viewer.
func (s *Store) Seats(orgID string) (Seats, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	o, ok := s.orgs[orgID]
	if !ok {
		return Seats{}, false
	}
	out := Seats{Used: s.seatsUsed(orgID)}
	if limit, limited := o.Plan.SeatLimit(); limited {
		out.Limit = &limit
	}
	return out, true
}

// seatsUsed counts the seats in use by an organization. The caller holds the lock.
func (s *Store) seatsUsed(orgID string) int {
	n := 0
	for _, m := range s.members {
		if m.OrgID == orgID && m.Role != RoleViewer {
			n++
		}
	}
	for _, inv := range s.invites {
		if inv.OrgID == orgID && inv.AcceptedAt == nil && inv.RevokedAt == nil && inv.Role != RoleViewer {
			n++
		}
	}
	return n
}

// checkFreeSeat returns a SeatError unless the organization's plan has a seat free for one more. The caller holds the
// lock.
func (s *Store) checkFreeSeat(orgID string) error {
	limit, limited := s.orgs[orgID].Plan.SeatLimit()
	if !limited {
		return nil
	}
	if used := s.seatsUsed(orgID); used+1 > limit {
		return &SeatError{Limit: limit, Used: used}
	}
	return nil
}

// checkPlanFits returns a SeatError unless the organization's seats in use fit within the plan's limit. The caller
// holds the lock.
func (s *Store) checkPlanFits(o Org) error {
	limit, limited := o.Plan.SeatLimit()
	if !limited {
		return nil
	}
	if used := s.seatsUsed(o.ID); used > limit {
		return &SeatError{Limit: limit, Used: used}
	}
	return nil
}

