args.content:
package store

import (
	"errors"
	"sync"
	"testing"
)

// seatMember adds a user with a role to an organization.
func seatMember(t *testing.T, s *Store, orgID, email string, role Role) User {
	t.Helper()
	u, err := s.CreateUser(email, email, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddMember(orgID, u.ID, role, t0); err != nil {
		t.Fatal(err)
	}
	return u
}

func seatsOf(t *testing.T, s *Store, orgID string) Seats {
	t.Helper()
	seats, ok := s.Seats(orgID)
	if !ok {
		t.Fatal("no seats for the organization")
	}
	return seats
}

func wantSeatError(t *testing.T, err error, limit, used int) {
	t.Helper()
	var se *SeatError
	if !errors.As(err, &se) || se.Limit != limit || se.Used != used {
		t.Fatalf("err = %v, want SeatError{Limit: %d, Used: %d}", err, limit, used)
	}
}

func TestSeatsOfPlans(t *testing.T) {
	s := New()
	free, _ := s.CreateOrg("Free", OrgFree, "UTC", 0, t0)
	business, _ := s.CreateOrg("Business", OrgBusiness, "UTC", 0, t0)
	seatMember(t, s, free.ID, "owner@free.example", RoleOwner)
	seatMember(t, s, free.ID, "viewer@free.example", RoleViewer)
	if got := seatsOf(t, s, free.ID); got.Used != 1 || got.Limit == nil || *got.Limit != 3 {
		t.Fatalf("free seats = %+v, want 1 used of 3", got)
	}
	if got := seatsOf(t, s, business.ID); got.Used != 0 || got.Limit != nil {
		t.Fatalf("business seats = %+v, want no limit", got)
	}
	if _, ok := s.Seats("org_nope"); ok {
		t.Fatal("seats of an unknown organization")
	}
}

func TestSeatsOnInvites(t *testing.T) {
	s := New()
	o, _ := s.CreateOrg("Free", OrgFree, "UTC", 0, t0)
	owner := seatMember(t, s, o.ID, "owner@free.example", RoleOwner)
	if _, err := s.CreateInvite(o.ID, "a@free.example", RoleMember, owner.ID, t0); err != nil {
		t.Fatal(err)
	}
	admin, err := s.CreateInvite(o.ID, "b@free.example", RoleAdmin, owner.ID, t0)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := s.CreateInvite(o.ID, "c@free.example", RoleMember, owner.ID, t0); err == nil {
		t.Fatal("an invite past the limit succeeded")
	} else {
		wantSeatError(t, err, 3, 3)
	}
	if _, err := s.CreateInvite(o.ID, "v@free.example", RoleViewer, owner.ID, t0); err != nil {
		t.Fatalf("a viewer invite needs no seat: %v", err)
	}

	// An accepted invite keeps its seat, so accepting never fails for lack of one.
	first := s.Invites(o.ID)[0]
	if _, _, _, err := s.AcceptInvite(first.Token, "A", t0); err != nil {
		t.Fatalf("accept at the limit: %v", err)
	}
	if got := seatsOf(t, s, o.ID); got.Used != 3 {
		t.Fatalf("seats after accepting = %+v, want 3 used", got)
	}

	// A revoked invite frees its seat.
	if _, err := s.RevokeInvite(o.ID, admin.ID, t0); err != nil {
		t.Fatal(err)
	}
	if got := seatsOf(t, s, o.ID); got.Used != 2 {
		t.Fatalf("seats after revoking = %+v, want 2 used", got)
	}
	if _, err := s.CreateInvite(o.ID, "d@free.example", RoleMember, owner.ID, t0); err != nil {
		t.Fatalf("invite into the freed seat: %v", err)
	}
}

func TestSeatsOnRoleChange(t *testing.T) {
	s := New()
	o, _ := s.CreateOrg("Free", OrgFree, "UTC", 0, t0)
	seatMember(t, s, o.ID, "owner@free.example", RoleOwner)
	viewer := seatMember(t, s, o.ID, "viewer@free.example", RoleViewer)
	member := seatMember(t, s, o.ID, "member@free.example", RoleMember)
	seatMember(t, s, o.ID, "admin@free.example", RoleAdmin)

	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleMember); err == nil {
		t.Fatal("a viewer became a member past the limit")
	} else {
		wantSeatError(t, err, 3, 3)
	}
	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleViewer); err != nil {
		t.Fatalf("a viewer stays a viewer: %v", err)
	}
	if _, err := s.SetMemberRole(o.ID, member.ID, RoleViewer); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SetMemberRole(o.ID, viewer.ID, RoleMember); err != nil {
		t.Fatalf("a viewer into the freed seat: %v", err)
	}
	if got := seatsOf(t, s, o.ID); got.Used != 3 {
		t.Fatalf("seats = %+v, want 3 used", got)
	}
}

func TestSeatsOnPlanChange(t *testing.T) {
	s := New()
	o, _ := s.CreateOrg("Acme", OrgTeam, "UTC", 0, t0)
	seatMember(t, s, o.ID, "owner@acme.example", RoleOwner)
	seatMember(t, s, o.ID, "m1@acme.example", RoleMember)
	seatMember(t, s, o.ID, "m2@acme.example", RoleMember)
	m3 := seatMember(t, s, o.ID, "m3@acme.example", RoleMember)

	downgrade := func(p OrgPlan) error {
		_, err := s.UpdateOrg(o.ID, func(o *Org) error { o.Plan = p; return nil })
		return err
	}
	if err := downgrade(OrgFree); err == nil {
		t.Fatal("a plan with 3 seats took 4 seats in use")
	} else {
		wantSeatError(t, err, 3, 4)
	}
	if got, _ := s.Org(o.ID); got.Plan != OrgTeam {
		t.Fatalf("plan after the refused change = %s", got.Plan)
	}
	if _, err := s.SetMemberRole(o.ID, m3.ID, RoleViewer); err != nil {
		t.Fatal(err)
	}
	if err := downgrade(OrgFree); err != nil {
		t.Fatalf("downgrade with seats to spare: %v", err)
	}
	if err := downgrade(OrgBusiness); err != nil {
		t.Fatalf("upgrade: %v", err)
	}
}

// Several invites sent at the same time for the last seat: exactly one succeeds.
func TestSeatsLimitHoldsUnderConcurrency(t *testing.T) {
	s := New()
	o := newOrg(t, s, "Acme")
	owner := seatMember(t, s, o.ID, "owner@acme.example", RoleOwner)
	for i := 0; i < 8; i++ {
		seatMember(t, s, o.ID, string(rune('a'+i))+"@acme.example", RoleMember)
	}
	if got := seatsOf(t, s, o.ID); got.Used != 9 {
		t.Fatalf("seats = %+v, want 9 used", got)
	}

	const invites = 6
	var wg sync.WaitGroup
	start := make(chan struct{})
	errs := make(chan error, invites)
	for i := 0; i < invites; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			_, err := s.CreateInvite(o.ID, string(rune('p'+i))+"@acme.example", RoleMember, owner.ID, t0)
			errs <- err
		}(i)
	}
	close(start)
	wg.Wait()
	close(errs)

	succeeded := 0
	for err := range errs {
		if err == nil {
			succeeded++
		}
	}
	if succeeded != 1 {
		t.Fatalf("%d of %d invites succeeded for one free seat, want 1", succeeded, invites)
	}
	if got := seatsOf(t, s, o.ID); got.Used != 10 {
		t.Fatalf("seats = %+v, want 10 used", got)
	}
}

