	s := New()
	o, _ := s.CreateOrg("Free", OrgFree, "UTC", 0, t0)
	owner := seatMember(t, s, o.ID, "owner@free.example", RoleOwner)
	if _, err := s.CreateInvite(o.ID, "a@free.example", RoleMember, owner.ID, t0); err != nil {
		t.Fatal(err)
