package api_test

import (
	"net/http"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

func TestSeatLimitOnInvites(t *testing.T) {
	e := apitest.New(t)
	free := e.NewOrg("Free", store.OrgFree, "UTC")
	e.AddMember(free, "m1@free.example", store.RoleMember)
	e.AddMember(free, "m2@free.example", store.RoleMember)

	r := e.Do("POST", "/v1/invites", free.Key, map[string]string{"email": "new@free.example", "role": "member"})
	if r.Code != http.StatusPaymentRequired {
		t.Fatalf("invite past the limit: %s", r)
	}
	body := r.Map(t)
	if body["error"] != "seat_limit_reached" || body["limit"] != float64(3) || body["used"] != float64(3) {
		t.Fatalf("body = %v", body)
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/invites", free.Key, map[string]string{"email": "v@free.example", "role": "viewer"}, nil)
}

func TestSeatLimitOnRoleChange(t *testing.T) {
	e := apitest.New(t)
	free := e.NewOrg("Free", store.OrgFree, "UTC")
	m1, _ := e.AddMember(free, "m1@free.example", store.RoleMember)
	e.AddMember(free, "m2@free.example", store.RoleMember)
	viewer, _ := e.AddMember(free, "v@free.example", store.RoleViewer)

	r := e.Do("PATCH", "/v1/members/"+viewer.ID, free.Key, map[string]string{"role": "member"})
	if r.Code != http.StatusPaymentRequired || r.Map(t)["error"] != "seat_limit_reached" {
		t.Fatalf("viewer becomes a member past the limit: %s", r)
	}
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+m1.ID, free.Key, map[string]string{"role": "viewer"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+viewer.ID, free.Key, map[string]string{"role": "member"}, nil)
}

func TestOverSeatLimitOnPlanChange(t *testing.T) {
	e := apitest.New(t)
	e.AddMember(e.Acme, "m1@acme.example", store.RoleMember)
	e.AddMember(e.Acme, "m2@acme.example", store.RoleMember)
	m3, _ := e.AddMember(e.Acme, "m3@acme.example", store.RoleMember)

	r := e.Do("PATCH", "/v1/org", e.Acme.Key, map[string]string{"plan": "free"})
	if r.Code != http.StatusConflict {
		t.Fatalf("downgrade over the limit: %s", r)
	}
	if body := r.Map(t); body["error"] != "over_seat_limit" || body["limit"] != float64(3) || body["used"] != float64(4) {
		t.Fatalf("body = %v", body)
	}
	var org struct {
		Plan  string `json:"plan"`
		Seats struct {
			Used  int  `json:"used"`
			Limit *int `json:"limit"`
		} `json:"seats"`
	}
	e.MustDo(http.StatusOK, "GET", "/v1/org", e.Acme.Key, nil, &org)
	if org.Plan != "team" || org.Seats.Used != 4 || org.Seats.Limit == nil || *org.Seats.Limit != 10 {
		t.Fatalf("org after the refused change = %+v", org)
	}

	e.MustDo(http.StatusOK, "PATCH", "/v1/members/"+m3.ID, e.Acme.Key, map[string]string{"role": "viewer"}, nil)
	e.MustDo(http.StatusOK, "PATCH", "/v1/org", e.Acme.Key, map[string]string{"plan": "free"}, nil)
}

